def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'

    defects = sum(1 for _, opp in history if opp == 'D')
    coops = n - defects

    if coops == 0:
        return 'D'

    recent_len = min(10, n)
    recent_def = sum(1 for _, opp in history[-recent_len:] if opp == 'D')

    if defects <= 1 and recent_def == 0:
        if n < 15:
            return 'C'
        if n == 15:
            return 'D'
        if n == 16:
            return 'C'
        return 'D'

    last_opp = history[-1][1]
    tail = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            tail += 1
        else:
            break

    if n >= 10 and defects * 2 > n:
        return 'D'

    if last_opp == 'D':
        if tail >= 3 or recent_def >= 5 or (tail >= 2 and defects * 2 > n):
            return 'D'
        return 'C'

    if recent_def >= 5:
        return 'D'
    return 'C'
